(() => {
 'use strict';
 const M=window.LabStoryModel,A=window.LabStoryArt;
 const chapters=['Первая проба','Подготовка','Исследования','Что говорят числа','Проверка','Передача смены'];
 const chapter=step=>{const i=M.steps.indexOf(step);return i<4?0:i<7?1:i<17?2:i<19?3:i<24?4:5;};
 const fmt=n=>Number(n).toFixed(1).replace('.',',');
 const copy={
 welcome:['По ту сторону этикетки','В каждой бутылке — работа целой команды. Сегодня ты узнаешь, как лаборант проверяет качество напитка.','Одна проба. Два прибора. Твоё первое заключение.'],
 intake:['С чего начинается исследование','Сначала найди пробу из направления. На столе несколько похожих бутылок, но каждая рассказывает о своей партии.','Нажми на бутылку с нужным номером.'],
 inspect:['У каждой пробы есть история','Номер, место отбора и целая упаковка помогают связать результат с нужной партией. Проверь три детали.','Нажимай на отмеченные детали бутылки и этикетки.'],
 register:['Теперь проба не потеряется','Всё совпало. Запись в журнале связывает образец, исследования и будущий результат.','Зарегистрируй пробу 07.'],
 temperature:['Сначала — правильные условия','Температура сейчас 24,3 °C. В нашей учебной методике указано 19–21 °C. Подготовим пробу по этим условиям.','Нажми на отметку у термостата, чтобы подготовить пробу.'],
 mix:['Одна бутылка — однородная проба','Аккуратно перемешаем образец. Тогда взятая порция будет лучше отражать его состав. Ничего в напиток не добавляем.','Нажми на бутылку: плавно перемешаем образец.'],
 portions:['Два исследования, две порции','Для каждого прибора нужна отдельная чистая ёмкость. Остатки после анализа не возвращают в исходный образец.','Подготовь порции для рефрактометра и pH-метра.'],
 'ref-control':['Можно ли доверять прибору?','Это рефрактометр. По преломлению света он помогает оценить растворённые вещества. Сначала проверим его на контрольном материале.','Измерь контрольный материал с известным значением.'],
 'ref-clean':['Чистая ячейка — точное начало','Контроль дал 10,0 °Bx, как указано в карточке. Теперь подготовим ячейку по методике: остатки контроля не должны попасть в пробу.','Нажми на салфетку, чтобы подготовить ячейку.'],
 'ref-load':['Всего одна капля','Нанеси порцию пробы на измерительную поверхность. °Brix — показание по шкале растворённых веществ; для напитка это не всегда точный процент сахара.','Выбери пипетку и нажми «Нанести каплю».'],
 'ref-close':['Закрываем крышку','Для этого учебного прибора закроем крышку перед измерением. Порядок действий всегда задаёт методика.','Нажми «Закрыть крышку».'],
 'ref-read':['Дадим прибору измерить','Огонёк на месте, крышка закрыта. Получим стабильное показание — именно его нужно сохранить.','Нажми клавишу измерения.'],
 'ref-record':['Число становится результатом','Прибор показывает 8,2 °Bx. Сохрани это число вместе с номером пробы. Пока не решаем, хороший ли напиток.','Впиши показание в журнал.'],
 'ph-rinse':['Другой вопрос — другой прибор','pH-метр показывает кислотность среды. Один рефрактометр не расскажет о напитке всё. Прибор уже проверен наставником; подготовим электрод.','Нажми на промывку электрода.'],
 'ph-dip':['Измерим кислотность','Используем отдельную порцию той же пробы. Опусти подготовленный электрод в образец.','Нажми «Опустить электрод».'],
 'ph-read':['Дождёмся устойчивого показания','Цифры могут меняться, пока электрод приходит в равновесие с пробой. Записываем стабильный результат.','Начни измерение pH.'],
 'ph-record':['Два числа, две характеристики','pH 3,6 — второй результат. Кислотность и растворённые вещества описывают разные свойства напитка.','Перенеси показание в журнал.'],
 compare:['Что здесь требует внимания?','Сравни каждый результат со своим диапазоном. На вид напиток обычный — именно поэтому нужны измерения.','Выбери показатель за пределами учебного диапазона.'],
 report:['Замеченное отклонение — полезный результат','Ты нашёл 8,2 °Bx при учебном диапазоне 9–11. Сохраним запись и сообщим наставнику. По одному числу причину не угадывают.','Отправь внутреннее игровое сообщение наставнику.'],
 'repeat-clean':['Проверяем, а не подгоняем','Наставник предложил проверить подготовку и повторить измерение новой порции. Температура и контроль прибора соответствуют методике.','Сначала снова подготовь измерительную ячейку.'],
 'repeat-load':['Новая порция той же пробы','Чистая ячейка и новая порция помогают проверить, повторится ли наблюдение. Исходный результат остаётся в журнале.','Выбери пипетку, затем нанеси новую порцию.'],
 'repeat-close':['Та же методика, те же условия','Чтобы сравнивать результаты, повторяем исследование при тех же условиях. Закрой крышку.','Нажми «Закрыть крышку».'],
 'repeat-read':['Повторное измерение','Иногда два результата немного отличаются. Важно оценить их по методике, а не добиваться удобного числа.','Измерь новую порцию.'],
 'repeat-record':['Отклонение подтвердилось','Теперь 8,3 °Bx — тоже ниже 9,0. Записываем повтор рядом с исходными 8,2; первая запись остаётся.','Впиши повторное показание.'],
 conclusion:['Твои данные нужны команде','Два измерения ниже диапазона. Что передадим ответственному специалисту? Лаборант отвечает за достоверные данные.','Выбери обоснованное действие.'],
 finish:['За маленькой пробой — большая ответственность','Ты прошёл путь лаборанта: от маркировки до измерений и сообщения об отклонении. Именно так данные помогают команде контролировать качество.','Первое знакомство с профессией состоялось.']
 };
 const lessons={trace:['Прослеживаемость','Результат имеет смысл, когда известно, к какой пробе и партии он относится.'],prep:['Подготовка','Чистота, температура и однородность образца влияют на измерение.'],brix:['Рефрактометрия','Рефрактометр измеряет преломление света. Шкала °Brix используется для оценки растворённых веществ с учётом состава продукта.'],ph:['Кислотность','pH описывает кислотность среды. Для неё нужен отдельный метод исследования.'],honesty:['Работа с данными','Неожиданное показание сохраняют. Повтор не заменяет исходную запись.'],team:['Командная работа','Лаборант сообщает результаты; дальнейшее решение по партии принимает уполномоченный специалист.']};
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function mount(host,options={}){
  let s,storageOK=true;try{s=M.normalize(JSON.parse(localStorage.getItem(M.KEY)));}catch{s=M.fresh();storageOK=false;}
  let busy=false,disposed=false,selected=false,notice='',modal='',sound=false,audio=null,animation=null,pending=null;
  const effects=new Set(),ghosts=new Set(),timers=new Set(),hiddenSources=new Set();
  function clearEffects(){hiddenSources.forEach(n=>n.style.visibility='');hiddenSources.clear();effects.forEach(a=>a.cancel());effects.clear();ghosts.forEach(n=>n.remove());ghosts.clear();timers.forEach(t=>clearInterval(t));timers.clear();}
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');let motion=!reduced.matches;
  for(const place of ['reception','preparation','optics','acidity','journal']){const img=new Image();img.src=`assets/lab-station-${place}.webp`;}
  const root=document.createElement('div');root.className='ls';host.replaceChildren(root);
  const button=(action,text,value='',cls='',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" data-value="${value}" ${attrs}>${text}</button>`;
  const action=(action,text,value='')=>button(action,text+A.icon('arrow'),value,'ls-primary');
  const save=()=>{try{localStorage.setItem(M.KEY,JSON.stringify(s));}catch{storageOK=false;}};
  const stepNumber=()=>M.steps.indexOf(s.step);
  const isRepeat=()=>s.step.startsWith('repeat-');
  function tone(success=false){if(!sound)return;try{audio||=new(window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(success?660:410,audio.currentTime);o.frequency.exponentialRampToValueAtTime(success?880:340,audio.currentTime+.12);g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.16);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.17);}catch{}}
  function room(){return `<div class="ls-room-art"><img src="assets/lab-station-reception.webp" alt="Приёмка проб: передаточное окно, стойка и лабораторный стол" draggable="false"></div>`;}
  function guide(){return `<img class="ls-world-guide" src="assets/lab-guide-illustrated.png" alt="Маскот Очаково — твой наставник" draggable="false">`;}
  function station(){if(['welcome','intake','inspect','register'].includes(s.step))return 'reception';if(['temperature','mix','portions'].includes(s.step))return 'preparation';if(s.step.startsWith('ref-')||isRepeat())return 'optics';if(s.step.startsWith('ph-'))return 'acidity';return 'journal';}
  const stationNames={reception:'Приёмка проб',preparation:'Подготовка образца',optics:'Рефрактометрия',acidity:'Измерение pH',journal:'Работа с результатами'};
  function paper(){return `<aside class="ls-direction"><span class="ls-eyebrow">Из технологического цеха</span><h3>Направление</h3><dl><div><dt>Проба</dt><dd>07</dd></div><div><dt>Место отбора</dt><dd>Ёмкость T-02</dd></div><div><dt>Время</dt><dd>12:30</dd></div><div><dt>Партия</dt><dd>P-214</dd></div></dl><p>Основа безалкогольного напитка,<br>до насыщения газом.</p></aside>`;}
  function roomScene(){
   if(s.step==='welcome')return `<div class="ls-scene room welcome">${room()}<section class="ls-intro"><span class="ls-eyebrow">ОЧАКОВО / ПЕРВАЯ СМЕНА</span><h1>По ту сторону<br><em>этикетки.</em></h1><p>Попробуй работу<br>химика-лаборанта.</p><div class="ls-meta"><span>7–10 минут</span><span>В твоём темпе</span></div>${action('start','Начать смену')}<span class="ls-intro-foot">Знание химии не требуется</span></section>${guide()}</div>`;
   return `<div class="ls-scene room">${room()}<div class="ls-sample-tray">${['08','07','09'].map(n=>button('sample',A.bottle(n)+`<span class="ls-object-label">Проба ${n}</span>`,n,'ls-object ls-sample',`aria-label="Взять пробу ${n}"`)).join('')}</div>${paper()}<div class="ls-scene-caption"><span>01</span> Приёмка проб</div></div>`;
  }
  function receipt(){
   const done=s.step==='register';
   return `<div class="ls-scene ls-bench receipt"><div class="ls-bench-lines"></div><div class="ls-receipt-bottle">${A.bottle('07',false,true)}</div>${paper()}${done?`<div class="ls-registration"><span class="ls-verified">${A.icon('check')} Данные проверены</span>${action('register','Зарегистрировать пробу')}</div>`:`<div class="ls-inspection">${[['number','07','Номер пробы'],['source','T-02','Источник и время'],['seal','✓','Целостность крышки']].map(([id,short,text])=>button('inspect',`<span class="ls-check-symbol">${s.checks.includes(id)?A.icon('check'):short}</span><span>${text}</span>`,id,`ls-check check-${id} ${s.checks.includes(id)?'checked':''}`,`aria-pressed="${s.checks.includes(id)}"`)).join('')}</div>`}<span class="ls-scene-caption">Этикетка и направление должны совпадать</span></div>`;
  }
  function preparation(){const st=s.step;return `<div class="ls-scene ls-bench preparation"><div class="ls-bench-lines"></div><div class="ls-prep-spec"><span class="ls-eyebrow">Учебная методика / 01</span><h3>Подготовка образца</h3><ol><li class="${st!=='temperature'?'done':''}">Температура 19–21 °C</li><li class="${st==='portions'?'done':''}">Аккуратно перемешать</li><li>Отдельная порция для каждого анализа</li></ol><small>Условия зависят от продукта и методики.</small></div><div class="ls-prep-zone"><div class="ls-temperature"><span>Температура образца</span><strong>${st==='temperature'?'24,3':'20,2'}<small> °C</small></strong><span class="${st==='temperature'?'amber':'green'}">${st==='temperature'?'Нужно подготовить':'Условия соблюдены'}</span></div>${button(st==='temperature'?'sample-display':st==='mix'?'mix':'portion',A.bottle('07')+`<span class="ls-object-label">${st==='temperature'?'Проба 07':st==='mix'?'Перемешать пробу':'Разделить на порции'}</span>`,'','ls-object ls-prep-bottle',`aria-label="${st==='temperature'?'Проба 07':st==='mix'?'Перемешать пробу':'Подготовить порции'}" ${st==='temperature'?'disabled':''}`)}<div class="ls-coaster"></div></div>${st==='portions'?`<div class="ls-portions"><div>${A.beaker(false,'A')}<span>Для °Brix</span></div><div>${A.beaker(false,'B')}<span>Для pH</span></div></div>`:''}${st==='temperature'?button('condition','<span class="ls-pin">↓</span><span>Подготовить температуру</span>','','ls-hotspot ls-bath-control','aria-label="Подготовить температуру"'):''}${st==='temperature'?button('skip-prep','Измерить сразу','','ls-temptation'):''}<span class="ls-scene-caption">${st==='temperature'?'Время подготовки в игре сокращено':'Сохраняем свойства исходного образца'}</span></div>`;}
  function recordForm(value,unit){return `<form class="ls-record-form"><label for="ls-reading">Запись в журнал · проба 07</label><div><input id="ls-reading" name="reading" inputmode="decimal" autocomplete="off" placeholder="0,0" aria-label="Показание прибора" required maxlength="6"><span>${unit}</span><button class="ls-primary" type="submit">Записать ${A.icon('check')}</button></div></form>`;}
  function refraction(){
   const st=s.step,repeat=isRepeat(),base=st.replace(/^(ref|repeat)-/,''),closed=['read','record'].includes(base),liquid=['close','read','record'].includes(base),value=base==='record'?(repeat?'8,3':'8,2'):base==='clean'&&!repeat?'10,0':'—';
   const instrumentAction=base==='control'?'control':base==='close'?'close':base==='read'?'measure':base==='load'?'well':'';
   const label={control:'Проверить прибор',close:'Закрыть крышку',read:'Измерить пробу',load:selected?'Нанести каплю':'Измерительная ячейка'}[base];
   return `<div class="ls-scene ls-bench refraction ${selected?'pipette-selected':''}" data-measurement="${value}"><div class="ls-bench-lines"></div><div class="ls-method"><span class="ls-eyebrow">${repeat?'Повтор / новая порция':'Исследование 01 / растворённые вещества'}</span><h3>Рефрактометр</h3><p>${repeat?'Исходный результат: 8,2 °Bx. Запись сохранена.':base==='control'?'Контрольный материал: 10,0 °Bx. Проверяем готовность до работы с пробой.':'Контроль: 10,0 °Bx — соответствует. Прибор готов к работе.'}</p><span class="ls-unit-note">°Bx · шкала Брикса</span></div><div class="ls-instrument-wrap">${A.device(value,closed,liquid)}<i class="ls-drop"></i></div><div class="ls-station-action">${instrumentAction?button(instrumentAction,`<span class="ls-pin">${base==='read'?A.icon('arrow'):base==='close'?'↓':base==='load'?'+':A.icon('check')}</span><span>${label}</span>`,'',`ls-hotspot hotspot-${base}`,`aria-label="${label}"`):''}</div><div class="ls-tools"><div class="ls-tool-bottle">${A.bottle(repeat?'07·R':'07·A',true)}<span>${repeat?'Новая порция':'Порция A'}</span></div>${base==='clean'?button('clean',A.cloth()+'<span>Подготовить ячейку</span>','','ls-object ls-cloth','aria-label="Подготовить ячейку"'):['load','close','read','record'].includes(base)?button('pipette',A.pipette()+`<span>${selected?'Огонёк готова':'Взять пипетку'}</span>`,'',`ls-object ls-pipette ${selected?'selected':''}`,base==='load'?'aria-label="Взять пипетку"':'disabled aria-label="Пипетка использована"'):''}</div>${base==='record'?recordForm(value,'°Bx'):''}<span class="ls-scene-caption">Учебные значения · требования зависят от напитка</span></div>`;
  }
  function ph(){const st=s.step,record=st==='ph-record',dipped=['ph-read','ph-record'].includes(st),act=st==='ph-rinse'?'rinse':st==='ph-dip'?'dip':'measure',label=st==='ph-rinse'?'Подготовить электрод':st==='ph-dip'?'Опустить электрод':'Измерить pH';return `<div class="ls-scene ls-bench ph"><div class="ls-bench-lines"></div><div class="ls-method"><span class="ls-eyebrow">Исследование 02 / кислотность</span><h3>pH-метр</h3><p>Отдельная порция B.<br>Готовность прибора проверена наставником.</p><span class="ls-unit-note">pH · кислотность среды</span></div><div class="ls-ph-wrap">${A.ph(record?'3,6':'—',dipped,st==='ph-rinse')}</div><div class="ls-station-action">${record?'':button(act,`<span class="ls-pin">${st==='ph-dip'?'↓':A.icon('arrow')}</span><span>${label}</span>`,'',`ls-hotspot ph-${act}`,`aria-label="${label}"`)}</div>${record?recordForm('3,6','pH'):''}<span class="ls-scene-caption">Учебные значения · один прибор не заменяет все исследования</span></div>`;}
  function rows(){return `<div class="ls-result-head"><span>Показатель</span><span>Результат</span><span>Учебный диапазон</span></div>${[['brix','Растворённые вещества','8,2 °Bx','9,0–11,0 °Bx'],['ph','Кислотность','3,6 pH','3,2–4,0 pH']].map(([v,n,r,range])=>button('compare',`<span>${n}</span><strong>${r}</strong><span>${range}</span>`,v,'ls-result-row',s.step==='compare'?'':'disabled')).join('')}`;}
  function results(){return `<div class="ls-scene ls-bench results"><div class="ls-bench-lines"></div><section class="ls-results-paper"><header><span class="ls-eyebrow">Лабораторный журнал / проба 07</span><span>P-214</span></header><h3>${s.step==='compare'?'Прочитай результат':'Сообщение наставнику'}</h3>${rows()}${s.step==='report'?`<div class="ls-report-note"><span class="ls-report-stamp">ОТКЛОНЕНИЕ</span><p>«Проба 07, партия P-214: получено 8,2 °Bx при учебном диапазоне 9–11 °Bx. pH в диапазоне. Прошу проверить результат вместе со мной».</p>${action('notify','Сообщить наставнику')}<small>Сообщение внутри игры. В компанию ничего не отправляется.</small></div>`:`<p class="ls-paper-tip">Нажми на строку, в которой результат выходит за границы.</p><div class="ls-range-illustration"><span>ниже</span><i></i><span>в диапазоне</span><i></i><span>выше</span></div>`}<footer>Все значения — учебные, а не нормы продукции «Очаково».</footer></section></div>`;}
  function conclusion(){return `<div class="ls-scene ls-bench conclusion"><div class="ls-bench-lines"></div><section class="ls-final-paper"><span class="ls-eyebrow">Партия P-214 / итог исследования</span><h3>Данные собраны.<br>Как поступим?</h3><div class="ls-readings"><div><span>Первое измерение</span><strong>8,2 <small>°Bx</small></strong></div><div><span>Повтор</span><strong>8,3 <small>°Bx</small></strong></div><div><span>Учебный диапазон</span><strong>9–11 <small>°Bx</small></strong></div></div><div class="ls-choices">${button('conclusion','Передать оба результата специалисту качества','report','ls-choice')}${button('conclusion','Разрешить выпуск: pH ведь в диапазоне','release','ls-choice')}${button('conclusion','Добавить сахар, чтобы исправить число','fix','ls-choice')}</div><p>Причина отклонения пока не установлена.</p></section></div>`;}
  function finish(){return `<div class="ls-scene finish">${guide()}<section class="ls-completion"><span class="ls-eyebrow">ПЕРВАЯ СМЕНА ЗАВЕРШЕНА</span><h2>Ты увидел то,<br>чего не видно<br><em>по этикетке.</em></h2><p>Надёжное измерение начинается<br>задолго до цифры на экране.</p><div class="ls-finish-ticks"><span>${A.icon('check')} Проба зарегистрирована</span><span>${A.icon('check')} Два исследования выполнены</span><span>${A.icon('check')} Отклонение проверено и передано</span></div>${action('profession','Ближе к профессии')}<div class="ls-finish-links">${button('download','Скачать журнал','','ls-text')}${button('restart','Пройти ещё раз','','ls-text')}</div></section></div>`;}
  function scene(){if(['welcome','intake'].includes(s.step))return roomScene();if(['inspect','register'].includes(s.step))return receipt();if(['temperature','mix','portions'].includes(s.step))return preparation();if(s.step.startsWith('ref-')||isRepeat())return refraction();if(s.step.startsWith('ph-'))return ph();if(['compare','report'].includes(s.step))return results();if(s.step==='conclusion')return conclusion();return finish();}
  function render(focus=false){
   const oldFocus=document.activeElement?.dataset?.action,chapterIndex=chapter(s.step),[title,mentor,instruction]=copy[s.step];
   const currentStation=station();root.dataset.travel=root.dataset.station!==currentStation?'yes':'no';root.dataset.station=currentStation;
   root.dataset.step=s.step;root.dataset.motion=motion?'on':'off';root.classList.toggle('ls-busy',busy);
   root.innerHTML=`<header class="ls-top"><a class="ls-back" href="index.html#map" aria-label="На карту завода">${A.icon('back')}</a><a class="ls-brand" href="index.html#map"><img src="assets/ochakovo-logo.png" alt="Очаково"></a><span class="ls-top-divider"></span><div class="ls-location"><b>Лаборатория</b><span>${stationNames[currentStation]}</span></div><nav aria-label="Управление игрой">${button('journal',A.icon('book')+'<span>Журнал</span><i>'+s.records.length+'</i>','','ls-nav', 'aria-label="Открыть журнал"')}${button('hint',A.icon('help')+'<span>Подсказка</span>','','ls-nav','aria-label="Подсказка"')}${button('pause',A.icon('pause'),'','ls-nav','aria-label="Пауза и настройки"')}</nav></header><div class="ls-progress" aria-label="Этапы смены">${chapters.map((n,i)=>`<div class="${i===chapterIndex?'current':i<chapterIndex?'past':''}" ${i===chapterIndex?'aria-current="step"':''}><span>${i<chapterIndex?'✓':String(i+1).padStart(2,'0')}</span><b>${n}</b></div>`).join('')}</div><section class="ls-playfield" aria-label="${title}">${scene()}${s.step!=='welcome'&&s.step!=='finish'?`<div class="ls-task-title"><span class="ls-eyebrow">${isRepeat()?'ПОВТОРНОЕ ИССЛЕДОВАНИЕ':'ТВОЯ ЗАДАЧА'}</span><h1>${title}</h1></div>`:''}</section><footer class="ls-coach"><div class="ls-mentor"><img src="assets/lab-guide-illustrated.png" alt="Наставник Очаково" draggable="false"></div><div class="ls-dialogue"><span class="ls-speaker">ТВОЙ НАСТАВНИК</span><p>${notice||mentor}</p><span class="ls-instruction ${notice?'is-notice':''}">${notice?'Попробуй ещё раз — мы никуда не спешим.':instruction}</span></div>${s.step!=='welcome'?button('why','Зачем это в работе?','','ls-why'):''}</footer><div class="ls-bottom"><span>${storageOK?'Прогресс сохраняется на этом устройстве':'Сохранение недоступно — не закрывай вкладку'}</span><span>Учебная история · без таймера и штрафов</span></div><div class="ls-live" role="status" aria-live="polite">${notice||title+'. '+instruction}</div><dialog class="ls-modal" aria-labelledby="ls-modal-title"></dialog>`;
   root.querySelector('form')?.addEventListener('submit',e=>{e.preventDefault();act('record',new FormData(e.target).get('reading'));});
   root.querySelector('.ls-modal').addEventListener('close',()=>{modal='';const b=root.querySelector(`[data-action="${lastModalTrigger}"]`);b?.focus({preventScroll:true});});
   if(focus){const target=root.querySelector('.ls-record-form input')||root.querySelector(`[data-action="${oldFocus}"]:not(:disabled)`)||root.querySelector('.ls-playfield button');target?.focus({preventScroll:true});}
  }
  let lastModalTrigger='pause';
  function showModal(kind){
   settle();modal=kind;lastModalTrigger=kind;const d=root.querySelector('.ls-modal');let content='';
   if(kind==='journal')content=`<span class="ls-eyebrow">ТВОИ НАБЛЮДЕНИЯ</span><h2 id="ls-modal-title">Лабораторный журнал</h2><p>Проба 07 · T-02 · 12:30 · партия P-214</p>${s.records.length?`<div class="ls-journal-records">${s.records.map(r=>`<div><span>${r.name}<small>${r.kind==='repeat'?'Новая порция · повтор':'Исходная запись'}</small></span><strong>${fmt(r.value)} ${r.unit}</strong></div>`).join('')}</div>`:'<p class="ls-empty">Показаний пока нет. Они появятся здесь, когда ты проведёшь измерения и запишешь результат.</p>'}<h3>Что ты уже открыл</h3>${s.discoveries.length?s.discoveries.map(id=>`<article class="ls-discovery"><b>${lessons[id][0]}</b><p>${lessons[id][1]}</p></article>`).join(''):'<p>Первое открытие ждёт тебя у приёмного стола.</p>'}<small>Числа в игре — учебные, не производственные нормы.</small>`;
   if(kind==='hint')content=`<span class="ls-eyebrow">МОЖНО НЕ СПЕШИТЬ</span><h2 id="ls-modal-title">Ближайшее действие</h2><p>${copy[s.step][2]}</p><p>${hint()}</p>${action('dismiss','Понятно, попробую')}`;
   if(kind==='why')content=`<span class="ls-eyebrow">О ПРОФЕССИИ</span><h2 id="ls-modal-title">${chapters[chapter(s.step)]}</h2><p>${why()}</p>${action('dismiss','Вернуться к пробе')}`;
   if(kind==='pause')content=`<span class="ls-eyebrow">ВРЕМЯ НА ВДОХ</span><h2 id="ls-modal-title">Смена подождёт</h2><p>Таймера нет. ${storageOK?'Твои действия сохранены на этом устройстве.':'Сохранение недоступно. Оставь вкладку открытой, чтобы продолжить.'}</p><div class="ls-settings">${button('toggle-sound',`Звуки <b>${sound?'Включены':'Выключены'}</b>`,'','ls-setting',`aria-pressed="${sound}"`)}${button('toggle-motion',`Анимации <b>${motion?'Включены':'Сокращены'}</b>`,'','ls-setting',`aria-pressed="${motion}"`)}</div>${action('dismiss','Продолжить смену')}${button('restart','Начать заново','','ls-text')}`;
   if(kind==='restart')content=`<h2 id="ls-modal-title">Начать новую смену?</h2><p>Текущий журнал этой лабораторной истории будет очищен. Остальные участки игры сохранятся.</p>${action('confirm-restart','Начать заново')}${button('dismiss','Остаться здесь','','ls-text')}`;
   if(kind==='profession')content=`<span class="ls-eyebrow">ХИМИК-ЛАБОРАНТ</span><h2 id="ls-modal-title">Внимательность,<br>которая меняет результат.</h2><p>Лаборант принимает и готовит пробы, работает с приборами, ведёт записи и помогает контролировать качество. В лаборатории исследуют разные объекты: воду, сырьё, напиток в процессе и готовую продукцию.</p><div class="ls-profession-grid"><article><h3>Что пригодится</h3><p>Интерес к химии, аккуратность, умение сравнивать данные и замечать детали.</p></article><article><h3>Как начинается работа</h3><p>Инструктаж, знакомство с методиками и обучение рядом с наставником. В материалах «Очаково» есть практика в лаборатории.</p></article></div><p>Ты попробовал часть рабочего дня. Реальные исследования выполняют по утверждённым методикам; решение по партии принимает уполномоченный специалист.</p><small>Источники: «Химик-лаборант.mp4», «Описание практики.docx», «Справочник студента» из материалов проекта. Сюжет и параметры — учебные. Игра не оценивает пригодность к работе.</small><div class="ls-modal-actions">${action('finish','Записать открытие')}${button('download','Скачать мой журнал','','ls-text')}<a href="index.html#careers">О практике в «Очаково» ↗</a></div>`;
   d.innerHTML=button('dismiss',A.icon('close'),'','ls-modal-close','aria-label="Закрыть"')+content;
   if(!d.open)d.showModal();d.querySelector('button')?.focus();
  }
  function hint(){const st=s.step;if(st==='intake')return 'Нужен номер 07: он указан в направлении справа.';if(st==='inspect')return 'Проверь номер, источник с временем и целостность крышки. Уже проверенные детали отмечены галочками.';if(st.endsWith('load'))return 'Сначала нажми на пипетку слева. Затем нажми «Нанести каплю» под прибором. Перетаскивать не обязательно.';if(st.endsWith('record'))return 'Посмотри на экран прибора. Запиши '+(st==='ph-record'?'3,6':st==='repeat-record'?'8,3':'8,2')+' в поле журнала.';if(st==='compare')return 'Растворённые вещества: 8,2 меньше 9,0. Именно эта строка требует внимания.';if(st==='conclusion')return 'Передай обе записи специалисту качества. Не изменяй напиток и не разрешай выпуск самостоятельно.';return copy[st][1];}
  function why(){return ['Даже точное число бесполезно, если его связали не с той партией. Маркировка и журнал позволяют восстановить путь образца и проверить, откуда появился результат.','Подготовка — часть исследования. Температура, чистота посуды и однородность пробы могут изменить показания. Для разных напитков нужны свои условия.','Каждый метод отвечает на свой вопрос. Рефрактометр помогает оценить растворённые вещества, pH-метр — кислотность. Готовность приборов проверяют, а результаты сохраняют с единицами измерения.','Красивый внешний вид не гарантирует соответствие требованиям. Лаборант сравнивает данные с методикой и сообщает об отклонении. Это полезная работа, а не провал смены.','Повтор помогает проверить наблюдение. Важно использовать новую порцию и сохранить исходные данные. Причину отклонения выясняют отдельно, вместе с командой.','Точность, честная запись и вовремя переданное наблюдение помогают технологам и специалистам качества принимать решения. Стажёр учится этому рядом с наставником.'][chapter(s.step)];}
  function download(){const text=['МОЯ ПЕРВАЯ СМЕНА · ЛАБОРАТОРИЯ ОЧАКОВО','Учебная модель. Параметры вымышлены.','Проба 07 · T-02 · 12:30 · P-214','',...s.records.map(r=>`${r.name}: ${fmt(r.value)} ${r.unit}`),'',...(s.completed?['Отклонение подтверждено повтором. Оба результата переданы ответственному специалисту в учебной истории.']:['Исследование ещё не завершено.']),'',...s.discoveries.map(id=>`${lessons[id][0]}: ${lessons[id][1]}`)].join('\n');const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='Моя первая смена — лабораторный журнал.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  function settle(){if(!pending)return;const p=pending;pending=null;animation?.cancel();animation=null;clearEffects();busy=false;s=p;save();render();}
  async function apply(result,keyboard){
   notice=result.message;selected=false;
   if(!result.accepted){s=result.state;save();tone();render(keyboard);return;}
   tone(true);pending=result.state;
   const st=s.step;let target=root.querySelector('.ls-playfield'),frames=[{opacity:1},{opacity:1}],duration=120;
   if(result.animation==='mix'){target=root.querySelector('.ls-prep-bottle');frames=[{transform:'translateY(0) rotate(0deg)'},{transform:'translateY(-12px) rotate(-14deg)'},{transform:'translateY(-12px) rotate(14deg)'},{transform:'translateY(-12px) rotate(-12deg)'},{transform:'translateY(-12px) rotate(12deg)'},{transform:'translateY(0) rotate(0deg)'}];duration=1800;}
   else if(result.animation==='drop'){
    const source=root.querySelector('.ls-pipette svg'),well=root.querySelector('.ls-drop');
    if(source&&well&&motion&&!document.hidden){hiddenSources.add(source.parentElement);source.parentElement.style.visibility='hidden';const sr=source.getBoundingClientRect(),wr=well.getBoundingClientRect(),rr=root.getBoundingClientRect(),ghost=document.createElement('div');ghost.className='ls-flight';ghost.innerHTML=source.outerHTML;Object.assign(ghost.style,{left:(sr.left-rr.left)+'px',top:(sr.top-rr.top)+'px',width:sr.width+'px',height:sr.height+'px'});root.append(ghost);ghosts.add(ghost);const dx=wr.left+wr.width/2-sr.left-sr.width*.53,dy=wr.top-40-sr.top-sr.height*.953;target=ghost;frames=[{transform:'translate(0,0) rotate(0deg)',offset:0},{transform:`translate(${dx}px,${dy}px) rotate(0deg)`,offset:.4},{transform:`translate(${dx}px,${dy}px) rotate(0deg)`,offset:.8},{transform:'translate(0,0) rotate(0deg)',offset:1}];duration=1700;const fall=well.animate([{opacity:0,transform:'translateY(-40px) scale(.5)'},{opacity:1,transform:'translateY(-34px) scale(1)'},{opacity:1,transform:'translateY(0) scale(.7)'},{opacity:0,transform:'translateY(4px) scale(1.8,.3)'}],{duration:450,delay:720,easing:'ease-in'});effects.add(fall);}
   }
   else if(result.animation==='close'){
    const lidFrames=Array.from({length:25},(_,i)=>A.lidFrame(82*(1-i/24)));duration=900;
    target=root.querySelector('.lid-face');frames=lidFrames.map(f=>({d:`path("${f.outer}")`}));
    if(motion&&!document.hidden)for(const [selector,key] of [['.lid-inset','inner'],['.lid-rim','rim']])effects.add(root.querySelector(selector).animate(lidFrames.map(f=>({d:`path("${f[key]}")`})),{duration,easing:'cubic-bezier(.4,0,.2,1)',fill:'forwards'}));
   }
   else if(result.animation==='dip'){target=root.querySelector('.electrode');frames=[{transform:'translateY(0)'},{transform:'translateY(45px)'}];duration=800;}
   else if(result.animation==='condition'){target=root.querySelector('.ls-temperature');frames=[{filter:'brightness(1)'},{filter:'brightness(1)'}];duration=1800;const n=target.querySelector('strong');if(motion&&!document.hidden){let tick=0;const values=['24,3','23,6','22,8','21,9','21,1','20,2'];const timer=setInterval(()=>{tick++;n.innerHTML=values[Math.min(tick,5)]+'<small> °C</small>';},280);timers.add(timer);}else n.innerHTML='20,2<small> °C</small>';}
   else if(result.animation==='measure'||result.animation==='control'){target=root.querySelector('.ls-instrument-wrap,.ls-ph-wrap');frames=[{filter:'brightness(1)'},{filter:'brightness(1.04)'},{filter:'brightness(1)'}];duration=1500;root.querySelector('.ls-instruction').textContent=result.animation==='control'?'Проверяем контрольный материал…':'Ждём стабильного показания…';if(motion&&!document.hidden){const display=target.querySelector('.meter-reading'),values=result.animation==='control'?['9,7','9,9','10,0']:st==='ph-read'?['3,9','3,7','3,6']:st==='repeat-read'?['8,0','8,2','8,3']:['7,8','8,0','8,2'];let i=0;display.textContent=values[i];const timer=setInterval(()=>{i++;display.textContent=values[Math.min(i,2)];},400);timers.add(timer);}}
   else if(result.animation==='clean'){const source=root.querySelector('.ls-cloth svg'),well=root.querySelector('.ls-drop');if(source&&well&&motion&&!document.hidden){hiddenSources.add(source.parentElement);source.parentElement.style.visibility='hidden';const sr=source.getBoundingClientRect(),wr=well.getBoundingClientRect(),rr=root.getBoundingClientRect(),ghost=document.createElement('div');ghost.className='ls-flight';ghost.innerHTML=source.outerHTML;Object.assign(ghost.style,{left:(sr.left-rr.left)+'px',top:(sr.top-rr.top)+'px',width:sr.width+'px',height:sr.height+'px'});root.append(ghost);ghosts.add(ghost);const dx=wr.left-sr.left-sr.width*.5,dy=wr.top-sr.top-sr.height*.5;target=ghost;frames=[{transform:'translate(0,0)',offset:0},{transform:`translate(${dx}px,${dy}px)`,offset:.35},{transform:`translate(${dx+20}px,${dy-5}px)`,offset:.5},{transform:`translate(${dx-15}px,${dy+5}px)`,offset:.65},{transform:`translate(${dx}px,${dy}px)`,offset:.8},{transform:'translate(0,0)',offset:1}];duration=1300;}}
   else if(result.animation==='rinse'){target=root.querySelector('.rinse-stream');frames=[{opacity:0,strokeDashoffset:0},{opacity:1,strokeDashoffset:-18,offset:.2},{opacity:1,strokeDashoffset:-90,offset:.85},{opacity:0,strokeDashoffset:-108}];duration=1600;}
   else if(result.animation==='portion'){
    target=root.querySelector('.ls-prep-bottle');target.style.transformOrigin='50% 50%';
    const tr=target.getBoundingClientRect(),sr=target.querySelector('svg').getBoundingClientRect(),rr=root.getBoundingClientRect(),cups=[...root.querySelectorAll('.ls-portions>div')].map(n=>n.getBoundingClientRect());
    const shadow=target.querySelector('svg>ellipse');if(shadow){hiddenSources.add(shadow);shadow.style.visibility='hidden';}const cap=target.querySelector('.bottle-cap');if(cap){hiddenSources.add(cap);cap.style.visibility='hidden';}
    const ox=tr.width/2,oy=tr.height/2,nx=sr.left-tr.left+sr.width*.5,ny=sr.top-tr.top+sr.height*65/300,angle=110*Math.PI/180;
    const rx=(nx-ox)*Math.cos(angle)-(ny-oy)*Math.sin(angle),ry=(nx-ox)*Math.sin(angle)+(ny-oy)*Math.cos(angle);
    const pour=r=>`translate(${r.left+r.width*.5-tr.left-ox-rx}px,${r.top-10-tr.top-oy-ry}px) rotate(110deg)`;
    frames=[{transform:'translate(0,0) rotate(0deg)',offset:0},{transform:pour(cups[0]),offset:.22},{transform:pour(cups[0]),offset:.42},{transform:pour(cups[1]),offset:.57},{transform:pour(cups[1]),offset:.79},{transform:'translate(0,0) rotate(0deg)',offset:1}];duration=2800;frames=frames.map(f=>({...f,easing:'cubic-bezier(.4,0,.2,1)'}));
    root.querySelectorAll('.beaker-liquid').forEach((el,i)=>{el.setAttribute('fill','#d9ac58');el.style.transformOrigin='center bottom';el.style.transformBox='fill-box';if(motion&&!document.hidden){effects.add(el.animate([{opacity:0,transform:'scaleY(.05)'},{opacity:.7,transform:'scaleY(1)'}],{duration:520,delay:i?1590:620,fill:'both',easing:'ease-in-out'}));const stream=document.createElement('i');stream.className='ls-pour-stream';Object.assign(stream.style,{left:(cups[i].left+cups[i].width*.5-rr.left)+'px',top:(cups[i].top-10-rr.top)+'px',height:(cups[i].width*.3)+'px'});root.append(stream);ghosts.add(stream);effects.add(stream.animate([{opacity:0},{opacity:.9,offset:.15},{opacity:.9,offset:.85},{opacity:0}],{duration:520,delay:i?1590:620,fill:'both'}));}});
   }
   busy=true;root.classList.add('ls-busy');
   if(motion&&!document.hidden&&target){animation=target.animate(frames,{duration,easing:result.animation==='portion'?'linear':'cubic-bezier(.4,0,.2,1)',fill:'forwards'});try{await animation.finished;}catch{}}
   if(disposed||!pending)return;
   s=pending;pending=null;animation=null;clearEffects();busy=false;save();render(keyboard);
  }
  function act(type,value,keyboard=false){
   if(['hint','journal','pause','why','profession','restart'].includes(type)){showModal(type);return;}
   if(type==='dismiss'){root.querySelector('dialog').close();return;}
   if(type==='toggle-sound'){sound=!sound;tone(true);showModal('pause');return;}
   if(type==='toggle-motion'){motion=!motion;root.dataset.motion=motion?'on':'off';showModal('pause');return;}
   if(type==='download'){download();return;}
   if(type==='finish'&&s.completed){root.querySelector('dialog')?.close();if(options.onComplete)options.onComplete();else {try{const key='ochakovo-first-shift-v3',raw=JSON.parse(localStorage.getItem(key)||'null'),data=raw&&typeof raw==='object'&&!Array.isArray(raw)?raw:{completed:{},storyVersion:0};if(!data.completed||typeof data.completed!=='object'||Array.isArray(data.completed))data.completed={};data.completed.lab={id:'lab',score:100,learned:'Принял и подготовил пробу, измерил °Brix и pH, сохранил исходные показания и повтор, передал подтверждённое отклонение специалисту качества.'};localStorage.setItem(key,JSON.stringify(data));location.href='index.html#complete/lab';}catch{notice='Смена завершена, но браузер не разрешил сохранить открытие. Ты можешь скачать свой журнал.';render();}}return;}
   if(type==='confirm-restart'){s=M.fresh();notice='';selected=false;modal='';save();render(true);return;}
   if(busy||modal)return;
   if(type==='pipette'&&s.step.endsWith('load')){selected=true;notice='';render(keyboard);return;}
   if(type==='well'){if(!selected){notice='Сначала возьми пипетку: она стоит слева от прибора.';render(keyboard);return;}type='drop';}
   apply(M.transition(s,type,value),keyboard);
  }
  function onClick(e){const b=e.target.closest('[data-action]');if(b&&!b.disabled&&root.contains(b))act(b.dataset.action,b.dataset.value,b.matches(':focus-visible'));}
  function onVisibility(){if(document.hidden)settle();}
  function onReduced(){motion=!reduced.matches;if(!motion)settle();root.dataset.motion=motion?'on':'off';}
  root.addEventListener('click',onClick);document.addEventListener('visibilitychange',onVisibility);reduced.addEventListener('change',onReduced);
  render();
  return {getState:()=>JSON.parse(JSON.stringify(s)),destroy(){settle();disposed=true;root.removeEventListener('click',onClick);document.removeEventListener('visibilitychange',onVisibility);reduced.removeEventListener('change',onReduced);audio?.close();root.remove();}};
 }
 window.LabStory={mount};
})();
